INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-01','Transformer Turns Ratio','Easy','EEE','arena','calculate','Electrical Machines','multiple_choice','A transformer has 500 primary turns and 100 secondary turns. If the primary voltage is 230 V (AC), what is the secondary voltage?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-02','DC Motor: Back-EMF','Easy','EEE','arena','predict','Electrical Machines','multiple_choice','As a DC motor accelerates to higher speed, its back-EMF (E_b) increases. This causes:','{"choices": ["Armature current to increase", "Armature current to decrease (I_a = (V_supply − E_b)/R_a)", "No change in armature current", "Motor to stall"], "correct": 1}'::jsonb,'I_a = (V_s − E_b) / R_a. As speed increases, E_b = K_ø × ω increases. (V_s − E_b) decreases → I_a decreases → torque decreases until motor reaches steady-state where motor torque = load torque. This is natural speed regulation.','{multiple_choice}'::text[],0.87) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-03','Induction Motor: Slip','Easy','EEE','arena','calculate','Electrical Machines','multiple_choice','A 4-pole induction motor runs on a 50 Hz supply. Synchronous speed = 1500 RPM. The rotor speed is 1440 RPM. What is the slip?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-04','Transformer: Core Losses','Easy','EEE','arena','classify','Electrical Machines','multiple_choice','Transformer core losses consist of:','{"choices": ["Copper losses only (I²R)", "Hysteresis and eddy current losses — both are functions of frequency and flux density; they are independent of load current", "Stray load losses", "Dielectric losses in insulation"], "correct": 1}'::jsonb,'Core (iron) losses: (1) Hysteresis loss: W_h = k_h × f × B_max^n (Steinmetz). (2) Eddy current loss: W_e = k_e × f² × B_max². Total core loss ≈ constant for fixed voltage/frequency — measured by open-circuit test.','{multiple_choice}'::text[],0.85) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-05','DC Motor Speed Control Methods','Easy','EEE','arena','select','Electrical Machines','multiple_choice','Speed of a separately-excited DC motor can be controlled by:','{"choices": ["Changing AC frequency only", "Armature voltage control (below base speed) or field weakening (above base speed, by reducing field current)", "Changing only the number of poles", "Using a higher-current supply"], "correct": 1}'::jsonb,'N ∝ (V_a − I_a R_a) / Φ. (1) Armature voltage control: V_a ↓ → N ↓ (constant flux, torque available). (2) Field weakening: Φ ↓ → N ↑ (constant armature voltage, reduced torque). These two methods cover the full speed range of DC drives.','{multiple_choice}'::text[],0.83) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-06','Three-Phase Induction Motor: Starting Current','Medium','EEE','arena','predict','Electrical Machines','multiple_choice','A squirrel-cage induction motor draws 6–8× full load current at direct-on-line (DOL) start. Why?','{"choices": ["The motor is inefficient at startup", "At standstill (s=1), rotor frequency = supply frequency; high rotor reactance limits power factor. The stator sees a nearly short-circuited transformer → high current drawn", "The load is too high at startup", "The power supply voltage drops at startup"], "correct": 1}'::jsonb,'At s=1: rotor reactance X_2s = sX_2 = X_2 (maximum). Low rotor resistance → high impedance from rotor appears low to stator → large magnetising and leakage currents. Methods to limit: star-delta, autotransformer, soft-starter, VFD.','{multiple_choice}'::text[],0.78) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-07','Transformer Short-Circuit Test','Medium','EEE','arena','interpret','Electrical Machines','multiple_choice','In the short-circuit test of a transformer, the secondary is short-circuited and reduced voltage applied to the primary until rated current flows. This test determines:','{"choices": ["Core loss and magnetising reactance", "Series equivalent impedance (winding resistances and leakage reactances) — since flux is low, core losses are negligible", "Open-circuit characteristic", "Insulation resistance"], "correct": 1}'::jsonb,'Short-circuit test (HV side energised, LV shorted): V_sc ≈ 5–10% of rated voltage → flux is small → core losses negligible. All measured power = I²R (copper losses at rated current). Calculates: Z_eq, R_eq, X_eq (series equivalent circuit parameters).','{multiple_choice}'::text[],0.76) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-08','Synchronous Generator: Voltage Regulation','Medium','EEE','arena','calculate','Electrical Machines','multiple_choice','A synchronous generator has no-load terminal voltage V_NL = 1100 V and full-load terminal voltage V_FL = 1000 V. Voltage regulation is:
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-09','Induction Motor: Torque-Slip Characteristic','Medium','EEE','arena','predict','Electrical Machines','multiple_choice','In the torque-slip characteristic of an induction motor, maximum torque (breakdown torque) occurs at:','{"choices": ["s = 1 (standstill)", "s = 0 (synchronous speed)", "Slip s = R₂/X₂ (where rotor resistance equals rotor reactance)", "s = 0.5"], "correct": 2}'::jsonb,'Maximum torque condition: dT/ds = 0 → s_max_T = R₂/X₂ (for normal motors, ≈ 0.1–0.2 at design). Beyond s_max_T: torque decreases with increasing slip → unstable region. Normal operation is in the stable region (s < s_max_T).','{multiple_choice}'::text[],0.72) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-10','Stepper Motor: Step Angle','Medium','EEE','arena','calculate','Electrical Machines','multiple_choice','A stepper motor has 200 steps per revolution. What is the step angle?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-11','BLDC Motor vs Brushed DC Motor','Medium','EEE','arena','compare','Electrical Machines','multiple_choice','BLDC (Brushless DC) motors are preferred over brushed DC motors in long-service applications because:','{"choices": ["BLDC motors are cheaper", "BLDC motors have higher starting torque", "BLDC motors have no brushes/commutator — no mechanical wear from arcing, no carbon dust, longer life, higher efficiency (no brush voltage drop), and operation at higher speeds", "BLDC motors operate on AC supply directly"], "correct": 2}'::jsonb,'Brushed DC: brushes wear → maintenance required (500–2000 hours). EMI from arcing. BLDC: electronic commutation (Hall sensors + MOSFET bridge) → no mechanical contacts → 10,000+ hours life, cleaner EMI, higher efficiency (~90% vs 75–85%), higher speed capability.','{multiple_choice}'::text[],0.78) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-12','Auto-Transformer vs Two-Winding Transformer','Medium','EEE','arena','compare','Electrical Machines','multiple_choice','An auto-transformer is more efficient than a two-winding transformer for voltage transformation ratios close to 1:1 because:','{"choices": ["It uses a higher core material quality", "Part of the power is transferred conductively (directly through winding) rather than magnetically — the transformer rating needed is smaller than the output kVA", "It has fewer losses at high voltages", "It eliminates eddy current losses completely"], "correct": 1}'::jsonb,'Auto-transformer: common winding shared between primary and secondary. For ratio a ≈ 1: most power transferred conductively, little magnetically. kVA rating of transformer = kVA_out × (1 − 1/a) << kVA_out. More economical, but no galvanic isolation (safety concern).','{multiple_choice}'::text[],0.68) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-13','Induction Motor: V/f Control','Hard','EEE','arena','interpret','Electrical Machines','multiple_choice','In variable-speed drives using V/f (volts-per-hertz) control, the ratio V/f is kept constant at frequencies below rated because:','{"choices": ["To keep rotor current constant", "To maintain constant air-gap flux (Φ ∝ V/f) — if flux is constant, available torque is constant; if V/f is not maintained (e.g., reduced voltage at low f), flux weakens and available torque drops", "To reduce copper losses", "To maintain constant efficiency"], "correct": 1}'::jsonb,'Air gap flux: Φ ∝ V/(2πfN) ∝ V/f. At low frequency without voltage boost, flux weakens → poor torque. V/f control: V/f = constant → constant flux → constant torque capability (constant torque region). Above rated frequency: V stays at rated → flux decreases → constant power region.','{multiple_choice}'::text[],0.72) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-14','Transformer: Efficiency Calculation','Hard','EEE','arena','calculate','Electrical Machines','multiple_choice','A 100 kVA transformer has iron losses P_i = 500 W, copper losses at full load P_cu = 1000 W. Efficiency at full load, unity power factor:
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-15','Synchronous Motor: Power Angle','Hard','EEE','arena','interpret','Electrical Machines','multiple_choice','In a synchronous motor, the power angle δ (torque angle) represents:','{"choices": ["The phase angle between voltage and current", "The angle between the rotor''s magnetic field and the stator''s rotating magnetic field — electrical angle between V_t and E_f phasors; maximum torque occurs at δ = 90°; beyond this, the motor loses synchronism", "The mechanical angle of the shaft", "The power factor angle"], "correct": 1}'::jsonb,'Synchronous motor power: P = (V_t × E_f / X_s) × sin(δ). Maximum at δ=90°. If δ exceeds 90° (overloaded), the motor pulls out of synchronism (pole slipping). Unlike induction motors, synchronous motors run at exactly synchronous speed in steady state.','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-16','Field-Oriented Control (FOC)','Hard','EEE','arena','interpret','Electrical Machines','multiple_choice','Field-Oriented Control (FOC, also called vector control) of induction motors achieves DC-motor-like torque response by:','{"choices": ["Using V/f control at all speeds", "Controlling stator current components independently: flux-producing component (d-axis) and torque-producing component (q-axis) in a rotating reference frame aligned with rotor flux", "Applying six-step commutation like BLDC motors", "Controlling only rotor resistance"], "correct": 1}'::jsonb,'FOC: transform 3-phase stator currents (Clarke transform) then to rotor-flux-aligned frame (Park transform). I_d controls flux (kept constant for constant torque operation); I_q directly controls torque (like DC armature current). Enables fast, precise torque control.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-17','Motor: Thermal Model and Derating','Hard','EEE','arena','interpret','Electrical Machines','multiple_choice','A motor''s continuous duty rating (S1) is derated for intermittent duty (S3 — periodic operation) because:','{"choices": ["Intermittent operation reduces efficiency", "During on-time, losses heat the motor; during off-time, it cools. At higher on/off duty cycles, the motor can handle higher output power without exceeding thermal limits", "Intermittent duty requires different insulation", "Starting losses are always higher than running losses"], "correct": 1}'::jsonb,'Thermal model: one-time-constant exponential heating/cooling. For S3 duty cycle D%: equivalent continuous power = D% × peak power. Higher duty cycle → lower permitted peak power for same temperature rise. IEC 60034-1 defines duty cycle ratings (S1–S10).','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-18','Transformer: Parallel Operation Conditions','Hard','EEE','arena','select','Electrical Machines','multiple_choice','For two transformers to be operated in parallel without circulating currents, they must have:','{"choices": ["Same physical size and weight", "Same voltage ratio, same per-unit impedance, and same vector group (phase displacement) — differences in any of these cause circulating currents that load the transformers without serving load", "Same manufacturer", "Same core material"], "correct": 1}'::jsonb,'Parallel transformer conditions: (1) Same voltage ratio → no voltage difference → no circulating current. (2) Same % impedance → load sharing proportional to kVA ratings. (3) Same vector group (e.g., both Dyn11) → no phase difference. Failure of any → circulating currents → overheating.','{multiple_choice}'::text[],0.65) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-19','Linear Induction Motor','Hard','EEE','arena','compare','Electrical Machines','multiple_choice','A linear induction motor (LIM) produces thrust instead of torque by:','{"choices": ["Using permanent magnets in the stator", "Unrolling the rotary induction motor — the rotating magnetic field becomes a linearly travelling field that induces current in a conducting plate (secondary) and produces a propulsion force", "Operating on DC instead of AC", "Using superconducting coils"], "correct": 1}'::jsonb,'LIM: primary (stator equivalent) with 3-phase windings creates a travelling magnetic field at velocity v_s = 2τf (τ=pole pitch, f=frequency). Secondary (conducting plate or rail) has induced currents. Thrust = motor analog of torque. Used in maglev, people movers, and coin sorting.','{multiple_choice}'::text[],0.6) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-20','Switched Reluctance Motor','Hard','EEE','arena','interpret','Electrical Machines','multiple_choice','A switched reluctance motor (SRM) produces torque by:','{"choices": ["Interaction of permanent magnet and stator current", "The tendency of the rotor poles (no windings) to align with the energised stator poles — rotor aligns to minimise reluctance (maximise flux) when a stator phase is excited; phased excitation produces continuous rotation", "Back-EMF interaction", "Eddy current induction in rotor"], "correct": 1}'::jsonb,'SRM: rotor has salient poles (no windings, no magnets). Stator phases excited sequentially → rotor reluctance torque (dL/dθ × i²/2). Simple, robust construction, fault-tolerant (phases independent), but: high torque ripple, acoustic noise, requires complex control. Used in washing machines, EV accessories.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-21','Induction Generator Operation','Hard','EEE','arena','interpret','Electrical Machines','multiple_choice','An induction motor can operate as a generator (induction generator) when:','{"choices": ["Operated on DC supply", "Driven above synchronous speed by an external prime mover — slip becomes negative; rotor''s induced EMF reversal causes power flow from rotor to stator (and to grid); reactive power still absorbed from grid", "Disconnected from the supply", "Field weakening is applied"], "correct": 1}'::jsonb,'Induction generator: N > N_s → s < 0 → power output. Still requires reactive power from grid (or capacitor bank) for magnetisation — no separate excitation. Used in wind turbines (squirrel cage SCIG), hydro. Simple and robust but poor VAR control.','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-22','Insulation Class: Temperature Rating','Hard','EEE','arena','interpret','Electrical Machines','multiple_choice','A motor with Class F insulation (rated max winding temperature 155°C) operates with a temperature rise of 100°C in a 40°C ambient. The thermal margin is:','{"choices": ["55°C hot spot margin", "15°C hot spot margin", "5°C hot spot margin", "No margin"], "correct": 1}'::jsonb,'Winding temperature = ambient + rise = 40 + 100 = 140°C. Class F limit = 155°C. Margin = 155 − 140 = 15°C. Standard practice: use Class F insulation with Class B temperature rise (80°C) for thermal margin and extended insulation life.','{multiple_choice}'::text[],0.68) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-23','Cogging Torque in PMSM','Hard','EEE','arena','diagnose','Electrical Machines','multiple_choice','Cogging torque in a permanent magnet synchronous motor (PMSM) is caused by:','{"choices": ["Imbalanced three-phase currents", "The tendency of rotor magnets to align with stator slots (preferential positions of minimum magnetic reluctance) — causes speed ripple, vibration, and audible noise particularly at low speeds", "Insufficient excitation current", "Brush contact resistance variation"], "correct": 1}'::jsonb,'Cogging (detent) torque: periodic torque variation as magnets pass over stator teeth. Frequency = N_slots × N_poles × speed. Mitigation: skewing of rotor magnets or stator slots, fractional slot winding, magnet pole shaping. Important for servo drives and precision motion control.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-24','Three-Phase Transformer: Delta-Wye Configuration','Hard','EEE','arena','interpret','Electrical Machines','multiple_choice','A Dyn11 transformer vector group means:','{"choices": ["Delta primary, star secondary with neutral, 30° phase shift (11 o''clock position = 330° or −30°)", "Double winding, yielding 11 kV output", "Dry-type transformer, 11 poles", "Delta-delta with 11 turns ratio"], "correct": 0}'::jsonb,'IEC vector group notation: D=delta, Y=star, y=star with neutral, Z=zigzag. Number (0–12) × 30° = phase displacement. Dyn11 = Delta primary, star+neutral secondary, 30° lag (secondary lags primary by 30°). Most common distribution transformer configuration (11 = −30°, equivalent to +330°).','{multiple_choice}'::text[],0.6) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-em-25','Wound Rotor Induction Motor: External Resistance','Hard','EEE','arena','interpret','Electrical Machines','multiple_choice','A wound rotor induction motor (WRIM) allows external resistance in the rotor circuit. Increasing rotor resistance:','{"choices": ["Reduces starting current only", "Shifts the maximum torque point to higher slip — allows starting with full torque at low current; at rated load, external resistance can be gradually removed for efficient running", "Increases motor speed above synchronous", "Reduces iron losses"], "correct": 1}'::jsonb,'WRIM: slip rings allow external resistor insertion. R₂_external shifts torque-slip curve: maximum torque occurs at s = R₂_total/X₂. Setting R₂_total = X₂ → maximum torque at s=1 (standstill) = maximum starting torque! Rotor efficiency = 1−s: higher slip → more rotor loss.','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
